with filtered as (select *, cast(event_time as date) as event_time_day from web_events where event_time > to_timestamp('2023-06-07 00:00:00') and page is not null), gaps as (select *, case when event_time - lag(event_time) over (partition by session_id order by event_time, id) > interval '30' day then 1 else 0 end as is_new_burst from filtered), sessionized as (select *, sum(is_new_burst) over (partition by session_id order by event_time, id rows between unbounded preceding and current row) as session_id_2 from gaps) select page, sort_array(collect_set(page)) as page_list, count(*) as cnt, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as span_minutes, avg(duration_sec) filter (where event_type = 'purchase') as purchase_avg_duration_sec, round(sum(session_id_2) / nullif(count(case when event_type = 'add_to_cart' then 1 end), 0), 2) as session_id_2_per_add_to_cart from sessionized group by page
